/*!40000 ALTER TABLE `consulta` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `dentista`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `dentista` (
  `id_dentista` int NOT NULL AUTO_INCREMENT,
  `nome` varchar(120) NOT NULL,
  `cro` varchar(20) NOT NULL,
  `especialidade` varchar(80) NOT NULL,
  `bio` text,
  `cor` varchar(7) NOT NULL DEFAULT '#12a3a0',
  `ativo` tinyint NOT NULL DEFAULT '1',
  `foto` varchar(120) DEFAULT NULL,
  `anos_experiencia` int DEFAULT NULL,
  `formacao` varchar(255) DEFAULT NULL,
  `publico` varchar(255) DEFAULT NULL,
  `condicoes` text,
  `atendimento` varchar(40) NOT NULL DEFAULT 'Presencial',
  PRIMARY KEY (`id_dentista`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `dentista` WRITE;
/*!40000 ALTER TABLE `dentista` DISABLE KEYS */;
INSERT INTO `dentista` VALUES (1,'Dra. Helena Duarte','CRO-SP 00.001','Ortodontia e Ortopedia Facial','Apaixonada por sorrisos alinhados, a Dra. Helena já acompanhou mais de 1.200 tratamentos ortodônticos. Trabalha com planejamento digital, aparelhos fixos estéticos e alinhadores transparentes, e explica cada etapa do tratamento para que o paciente acompanhe a evolução do próprio sorriso. Atende desde crianças em fase de crescimento até adultos que decidiram corrigir o sorriso depois dos 40.','#12a3a0',1,'helena.svg',14,'Graduação em Odontologia, especialização em Ortodontia e Ortopedia Facial dos Maxilares e certificação em alinhadores invisíveis.','Crianças (a partir de 7 anos), adolescentes e adultos','Alinhadores invisíveis\nAparelho fixo estético (safira e cerâmica)\nCorreção de má oclusão e apinhamento\nMordida cruzada, aberta e sobremordida profunda\nFechamento de diastemas\nDisfunção temporomandibular (DTM) e bruxismo','Presencial'),(2,'Dr. Rafael Monteiro','CRO-SP 00.002','Implantodontia e Cirurgia Oral','São 18 anos dedicados à reabilitação oral e mais de 2.500 implantes instalados. O Dr. Rafael usa tomografia e cirurgia guiada para procedimentos mais rápidos, previsíveis e confortáveis, com acompanhamento próximo no pós-operatório. Seu objetivo é devolver ao paciente a segurança de mastigar, falar e sorrir sem preocupação.','#0b3a75',1,'rafael.svg',18,'Graduação em Odontologia, especialização em Implantodontia e mestrado em Cirurgia e Traumatologia Bucomaxilofacial.','Adultos e idosos (a partir de 18 anos)','Implantes dentários unitários e múltiplos\nProtocolo All-on-4 (prótese fixa sobre implantes)\nEnxerto ósseo e levantamento de seio maxilar\nCirurgia guiada por tomografia\nExtração de sisos inclusos\nCarga imediata','Presencial'),(3,'Dra. Camila Nogueira','CRO-SP 00.003','Estética e Harmonização Orofacial','A Dra. Camila une técnica e olhar artístico para criar sorrisos naturais. Há 10 anos se dedica a clareamentos, lentes de contato, restaurações estéticas e harmonização orofacial (toxina botulínica e preenchimento com ácido hialurônico), sempre buscando um resultado equilibrado e natural, com atendimento calmo e acolhedor.','#4f7cc4',1,'camila.svg',10,'Graduação em Odontologia, especialização em Dentística Restauradora e em Harmonização Orofacial.','Todas as idades: crianças, adultos e idosos','Clareamento dental\nLentes de contato e facetas\nHarmonização orofacial\nToxina botulínica (botox)\nPreenchimento com ácido hialurônico\nRestaurações estéticas em resina','Presencial');
/*!40000 ALTER TABLE `dentista` ENABLE KEYS */;
UNLOCK TABLES;
